import {sceneNames,sceneUrl,getScene,loadScene,fixedScenes,isImageScene} from './scene-library.js';
import {categories,labels,formats,motifs,defaults,render,drawBackground} from './design-engine.js';
const params=new URLSearchParams(location.search),productId=['radio-launch','clan-launch'].includes(params.get('package'))?params.get('package'):'designstudio';
const $=s=>document.querySelector(s),canvas=$('#canvas'),ctx=canvas.getContext('2d');let state=defaults(new URLSearchParams(location.search).get('category')||'radio');if(!categories.includes(state.category))state=defaults();if(productId!=='designstudio')state=packageDefaults();let selected=0,history=[],drag=null,loadToken=0,sceneMessage='';
const clone=x=>JSON.parse(JSON.stringify(x));function remember(){history.push(clone(state));if(history.length>35)history.shift()}
function paint(){$('#status').textContent='';const [w,h]=formats[state.format];if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}render(ctx,state,{guides:$('#guides').checked,selected,watermark:true});const safe=state.format==='youtube'?[508,508,1544,424]:state.format==='facebook'?[440,280,800,250]:null;if(safe){const [sx,sy,sw,sh]=safe;const outside=state.texts.some(t=>{ctx.font=`${t.size*w/1920}px ${t.font==='condensed'?'Designer':t.font==='serif'?'Georgia':t.font==='mono'?'monospace':'Arial'}`;const tw=Math.min(w*.9,ctx.measureText(t.text).width),th=t.size*w/1920;return t.x*w-tw/2<sx||t.x*w+tw/2>sx+sw||t.y*h-th/2<sy||t.y*h+th/2>sy+sh});$('#status').textContent=outside?'Achtung: Text außerhalb des Titelbild-Sicherheitsbereichs. Position oder Größe anpassen.':'';}if(sceneMessage)$('#status').textContent=sceneMessage;$('#total').textContent=state.service?(productId==='designstudio'?'278,00 €':'178,00 €'):'79,00 €';}
function packageDefaults(){const k=productId==='radio-launch'?'radio':'gaming';return {...defaults(k),collection:productId+'-v2',accent:k==='radio'?'#65edff':'#68f4d0',secondary:k==='radio'?'#78aaff':'#8cb6ff'};}
function backgroundNames(){if(fixedScenes[state.collection])return [fixedScenes[state.collection].name];return state.collection==='premium-v2'?sceneNames[state.category]:motifs}
function thumbs(){const box=$('#backgrounds');box.replaceChildren();const select=$('#background');select.replaceChildren();backgroundNames().forEach((name,i)=>{select.add(new Option(name,i));const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(i===state.background));button.setAttribute('aria-label',name);let thumb;if(isImageScene(state)){thumb=document.createElement('img');thumb.src=sceneUrl({...state,background:i},true);thumb.alt='';thumb.loading='lazy';thumb.width=220;thumb.height=125;}else{thumb=document.createElement('canvas');thumb.width=220;thumb.height=125;drawBackground(thumb.getContext('2d'),220,125,{...state,background:i});}button.append(thumb,document.createTextNode(name));button.onclick=()=>{remember();state.background=i;sync()};box.append(button)});select.value=state.background;}
function prepareScene(){const token=++loadToken,s=clone(state);if(isImageScene(s)&&!getScene(s)){sceneMessage='Bildkulisse wird geladen …';loadScene(s).then(()=>{if(token!==loadToken)return;sceneMessage='';paint()}).catch(e=>{if(token!==loadToken)return;sceneMessage=e.message;paint()})}else sceneMessage='';}
async function exportState(){const s=clone(state);await loadScene(s);await document.fonts.ready;return s;}
function syncText(){const select=$('#textIndex');select.replaceChildren();state.texts.forEach((t,i)=>select.add(new Option(`Text ${i+1}: ${t.text.slice(0,20)}`,i)));select.value=selected;const t=state.texts[selected];for(const [id,value] of Object.entries({text:t.text,font:t.font,textColor:t.color,size:t.size,x:t.x*100,y:t.y*100}))$('#'+id).value=value;}
function sync(){for(const key of ['category','collection','format','background','accent','secondary','frame','ambience','intensity'])$('#'+key).value=state[key];document.querySelector(`[name=service][value=${state.service?'full':'self'}]`).checked=true;syncText();thumbs();prepareScene();paint()}
categories.forEach(k=>$('#category').add(new Option(labels[k],k)));Object.entries(formats).forEach(([k,[w,h,label]])=>$('#format').add(new Option(`${label} · ${w}×${h}`,k)));motifs.forEach((s,i)=>$('#background').add(new Option(s,i)));
for(const key of ['category','collection','format','background','accent','secondary','frame','ambience','intensity'])$('#'+key).addEventListener('change',e=>{remember();state[key]=['background','intensity'].includes(key)?Number(e.target.value):e.target.value;if(key==='category')state.background=0;sync()});
$('#textIndex').onchange=e=>{selected=Number(e.target.value);syncText();paint()};for(const key of ['text','font','textColor','size','x','y'])$('#'+key).addEventListener('input',e=>{remember();const t=state.texts[selected];if(key==='x'||key==='y')t[key]=Number(e.target.value)/100;else if(key==='size')t.size=Number(e.target.value);else t[key==='textColor'?'color':key]=e.target.value;paint()});
$('#addText').onclick=()=>{if(state.texts.length>=6)return notice('Bis zu sechs Textebenen möglich.');remember();state.texts.push({text:'DEIN TEXT',x:.5,y:.68,size:40,font:'sans',color:state.accent});selected=state.texts.length-1;sync()};$('#removeText').onclick=()=>{if(state.texts.length===1)return;remember();state.texts.splice(selected,1);selected=0;sync()};$('#undo').onclick=()=>{if(history.length){state=history.pop();selected=Math.min(selected,state.texts.length-1);sync()}};$('#reset').onclick=()=>{remember();state=productId==='designstudio'?defaults(state.category):packageDefaults();selected=0;sync()};$('#guides').onchange=paint;document.querySelectorAll('[name=service]').forEach(el=>el.onchange=()=>{state.service=el.value==='full';paint()});
function pos(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
canvas.onpointerdown=e=>{const p=pos(e);let best=-1,d=.15;state.texts.forEach((t,i)=>{const distance=Math.abs(p.y-t.y);if(distance<d&&Math.abs(p.x-t.x)<.45){best=i;d=distance}});if(best<0)return;selected=best;remember();drag={x:p.x-state.texts[best].x,y:p.y-state.texts[best].y};canvas.setPointerCapture(e.pointerId);syncText();paint()};canvas.onpointermove=e=>{if(!drag)return;const p=pos(e),t=state.texts[selected];t.x=Math.max(.05,Math.min(.95,p.x-drag.x));t.y=Math.max(.05,Math.min(.95,p.y-drag.y));syncText();paint()};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
function notice(s){$('#status').textContent=s}function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#saveDraft').onclick=()=>download('NeonMind-Entwurf.json',JSON.stringify(state,null,2),'application/json');$('#loadDraft').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const s=JSON.parse(await input.files[0].text());if((s.collection!==undefined&&!['premium-v2','legacy',productId+'-v2'].includes(s.collection))||!categories.includes(s.category)||!formats[s.format]||!Array.isArray(s.texts)||s.texts.length<1||s.texts.length>6||s.texts.some(t=>typeof t.text!=='string'||t.text.length>80||!Number.isFinite(t.x)||!Number.isFinite(t.y)||!Number.isFinite(t.size)||t.x<.05||t.x>.95||t.y<.05||t.y>.95||t.size<12||t.size>240||!['condensed','sans','serif','mono'].includes(t.font)||!/^#[a-f0-9]{6}$/i.test(t.color))||!Number.isInteger(s.background)||s.background<0||s.background>9||!/^#[a-f0-9]{6}$/i.test(s.accent)||!/^#[a-f0-9]{6}$/i.test(s.secondary)||!['none','full','lines','corners'].includes(s.frame)||!['none','beams','particles','equalizer'].includes(s.ambience)||!Number.isFinite(s.intensity)||s.intensity<0||s.intensity>100)throw Error();remember();state={...s,collection:s.collection||'legacy'};state.service=s.service===true;selected=0;sync();notice('Entwurf geladen.')}catch{notice('Diese Datei ist kein gültiger Designentwurf.')}};input.click()};$('#previewDownload').onclick=async()=>{try{const saved=await exportState();const c=document.createElement('canvas');[c.width,c.height]=formats[saved.format];render(c.getContext('2d'),saved,{watermark:!location.protocol.startsWith('file')});const a=document.createElement('a');a.download='NeonMind-'+state.format+'-Vorschau.png';a.href=c.toDataURL('image/png');a.click()}catch(e){notice(e.message)}};
$('#buy').onclick=()=>{try{let cart=JSON.parse(localStorage.getItem('nm-cart')||'[]');if(!Array.isArray(cart))cart=[];cart=cart.filter(s=>typeof s==='string'&&/^[a-z0-9-]{1,48}$/.test(s)&&s!==productId+'-personalisierung');cart.push(productId);if(state.service)cart.push(productId+'-personalisierung');localStorage.setItem('nm-cart',JSON.stringify([...new Set(cart)]));localStorage.setItem('nm-design-draft',JSON.stringify({...state,productId}));location.href='/checkout'}catch{notice('Dein Browser blockiert das Speichern. Bitte Speicherzugriff erlauben.')}};
const svgButton=document.createElement('button');svgButton.textContent='SVG-Entwurf herunterladen';$('.actions').append(svgButton);svgButton.onclick=async()=>{try{const saved=await exportState();const c=document.createElement('canvas');[c.width,c.height]=formats[saved.format];drawBackground(c.getContext('2d'),c.width,c.height,saved);const xml=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');const text=saved.texts.map(t=>`<text x="${t.x*c.width}" y="${t.y*c.height}" font-size="${t.size*c.width/1920}" font-family="${t.font==='condensed'?'Barlow Condensed':t.font==='serif'?'Georgia':t.font==='mono'?'monospace':'Arial'}" text-anchor="middle" dominant-baseline="middle" fill="${t.color}">${xml(t.text)}</text>`).join('');download('NeonMind-Textentwurf.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="${c.width}" height="${c.height}" viewBox="0 0 ${c.width} ${c.height}"><image width="${c.width}" height="${c.height}" href="${c.toDataURL('image/png')}"/>${text}<text x="20" y="40" fill="#fff" font-family="Arial" font-size="20">${location.protocol.startsWith('file')?'':'NEONMIND / VORSCHAU'}</text></svg>`,'image/svg+xml');notice('SVG mit bearbeitbaren Texten gesichert. Rahmen und Ambiente sind in der PNG-Ausgabe enthalten.');}catch(e){notice(e.message)}};if(productId!=='designstudio'){const fixed=fixedScenes[productId+'-v2'];$('#collection').add(new Option('Festes Paketmotiv · '+fixed.name,productId+'-v2'));for(const key of ['category','collection','background'])$('#'+key).disabled=true;$('.intro h1').textContent=productId==='radio-launch'?'Dein Radio. Dein Auftritt.':'Dein Clan. Dein Auftritt.';$('.intro p').textContent=fixed.name+' ist das feste Bildmotiv dieses Pakets. Passe Texte, Farben und Rahmen an. Das Motiv gehört ausschließlich zu diesem Paketangebot und ist nicht in den 60 individuellen Studio-Kulissen enthalten.';$('.notes h2').textContent='Ein Paket. Ein eigenes festes Bildmotiv.';$('.notes p').textContent='50 Masterlayouts mit PNG, PSD-Textebenen und SVG sowie Website und Mediakit. Die Vorschau ergänzt deine Bestellung als Orientierung; die Paketdateien werden durch den Entwurf nicht automatisch neu erzeugt. Persönliche Übertragung optional +99 €.';document.querySelector('.choice b').textContent='Paket zum Selbstanpassen · 79 €';document.querySelector('.choice small').textContent='50 fertige Masterlayouts mit PNG, PSD und SVG. Dein Entwurf ergänzt die Bestellung als Orientierung; fertige Paketdateien werden dadurch nicht automatisch neu gerendert.';document.querySelectorAll('.choice b')[1].textContent='Persönliche Paketanpassung · +99 €';document.querySelectorAll('.choice small')[1].textContent='Ein Name, vorhandenes Logo, gelieferte Texte/Links, eine Korrekturrunde. Wir übertragen deinen Entwurf auf die Paketgrafiken. Termin nach Briefing.';}if(params.get('review')==='1'){try{const draft=JSON.parse(localStorage.getItem('nm-design-draft'));if(draft&&categories.includes(draft.category)&&formats[draft.format]&&Array.isArray(draft.texts)&&draft.texts.length)state={...draft,collection:draft.collection||'legacy'}}catch{}}document.fonts.ready.then(paint);sync();
